{{ config(materialized='incremental') }}
/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_AGREEMENT_SLA
   anchor      : HUB_AGREEMENT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_AGREEMENT_HK
   hashdiff    : SAT_AGREEMENT_SLA_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_AGREEMENT|' || (HUB_AGREEMENT_BK__HOSID))) as HUB_AGREEMENT_HK
        , CLAIM_PYMT_TAT as TAT_COMMITMENT
        , BILL_REC_TIME as SERVICE_LEVEL_TARGET
        , 'BJAZ_HM_HOSPITAL_MASTER_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master_extn') }}
    where (nullif(trim(HOSID),'')) is not null
),

resolved as (
    select
        HUB_AGREEMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TAT_COMMITMENT end) as TAT_COMMITMENT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SERVICE_LEVEL_TARGET end) as SERVICE_LEVEL_TARGET,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_AGREEMENT_HK
),

hashed as (
    select
        *,
        case when TAT_COMMITMENT is not null or SERVICE_LEVEL_TARGET is not null
                     then md5(upper(coalesce(cast(TAT_COMMITMENT as varchar), '') || '|' || coalesce(cast(SERVICE_LEVEL_TARGET as varchar), '')))
                end as SAT_AGREEMENT_SLA_HASHDIFF
    from resolved
)

select * from hashed
where HUB_AGREEMENT_HK is not null
  and SAT_AGREEMENT_SLA_HASHDIFF is not null
